$ErrorActionPreference='Stop'
Add-Type -AssemblyName PresentationFramework
$root=Split-Path $PSScriptRoot -Parent;$source=Get-Content -LiteralPath (Join-Path $root 'widget.ps1') -Raw
$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($source,[ref]$tokens,[ref]$errors);if($errors.Count){throw ($errors.Message -join '; ')}
foreach($name in @('Get-Palette','Brush','Alpha','Normalize-WidgetOpacity','Surface-Brush','New-WidgetMenuStyles','Set-WidgetMenuItems','Set-WidgetMenuTheme','Set-WidgetControlTheme','Remap-Tree','Apply-Theme','Set-Theme','Test-AppearanceRecord','Receive-Appearance','Request-Appearance','New-Text','Level-Brush','Load-Thr','Save-Settings','Get-WidgetPlacement','Update-Widget','Show-Toast')){$fn=$ast.Find({param($n)$n -is [Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq $name}.GetNewClosure(),$true);if(-not $fn){throw "Missing compact contract $name"};. ([scriptblock]::Create($fn.Extent.Text))}
function Log($m){$script:lastLog=$m}
function Get-SysLight{return $script:testSystemLight}
$script:S=@{theme='light';palette='teal';opacity=.96;muteAlerts=$true};$script:C=Get-Palette $true;$script:isLight=$true;$script:brushCache=@{};$script:backgroundSurfaces=New-Object Collections.ArrayList;$script:appearanceRevision=-1;$script:appearanceRecoveryRequired=$false;$script:testSystemLight=$true
$a=$source.IndexOf('# ------------------------------------------------------------------ window skeleton');$b=$source.IndexOf('# ------------------------------------------------------------------ backend access',$a)
$uiSource=$source.Substring($a,$b-$a).Replace("(Join-Path `$PSScriptRoot 'assets\icon_192.png')","(Join-Path `$root 'assets\icon_192.png')")
. ([scriptblock]::Create($uiSource))
$script:sync=@{data=$null;appearance=$null;lastAt=Get-Date;err=$null};$script:THR=@{ramW=80;ramB=92;dW=40;dB=20};$script:appearanceMenuItems=@();$menu=New-Object Windows.Controls.ContextMenu
function Layout-Compact{$surface=$win.Content;$surface.Measure([Windows.Size]::new(340,[double]::PositiveInfinity));$height=[Math]::Ceiling($surface.DesiredSize.Height);$surface.Arrange([Windows.Rect]::new(0,0,340,$height));$surface.UpdateLayout();return $height}
function Fresh-Data{return @{now=(Get-Date).ToString('s');m=@{ramPct=45;diskFreeGB=148;diskPct=61};cpuNow=@{pct=24;age=1}}}
function Lum($c){$v=@();foreach($p in @($c.R,$c.G,$c.B)){$n=[double]$p/255.0;$v+=if($n -le .04045){$n/12.92}else{[Math]::Pow(($n+.055)/1.055,2.4)}};return .2126*$v[0]+.7152*$v[1]+.0722*$v[2]}
function Ratio($a,$b){$x=Lum $a;$y=Lum $b;return ([Math]::Max($x,$y)+.05)/([Math]::Min($x,$y)+.05)}
function Text-Nodes($node){$out=@();if($node -is [Windows.Controls.TextBlock] -or $node -is [Windows.Controls.AccessText]){$out+=$node};for($i=0;$i -lt [Windows.Media.VisualTreeHelper]::GetChildrenCount($node);$i++){$out+=Text-Nodes ([Windows.Media.VisualTreeHelper]::GetChild($node,$i))};return $out}
$script:sync.data=Fresh-Data;Update-Widget;$height=Layout-Compact
if($source -match 'ScrollViewer|Primitives.ScrollBar|Controls.Expander|detailSections|New-Ring|Start-Clean|/api/run-cleanup|/api/trim-memory|/api/tier-pause'){throw 'Compact source retains scrolling/pages or maintenance commands'}
$script:buttons=New-Object Collections.ArrayList
function Check-Tree($node){if($node -isnot [Windows.DependencyObject]){return};if($node -is [Windows.Controls.ScrollViewer] -or $node -is [Windows.Controls.Expander] -or $node -is [Windows.Controls.Primitives.ScrollBar]){throw 'Actual compact tree contains scrolling or expansion'};if($node -is [Windows.Controls.Primitives.ButtonBase]){[void]$script:buttons.Add($node)};foreach($child in [Windows.LogicalTreeHelper]::GetChildren($node)){Check-Tree $child}}
Check-Tree $win.Content;if($script:buttons.Count -ne 3 -or $UI.open.Content -ne 'فتح التطبيق'){throw 'Compact tree has extra controls or unclear opener'}
$peer=[Windows.Automation.Peers.ButtonAutomationPeer]::new($UI.open);if(-not $peer.GetPattern([Windows.Automation.Peers.PatternInterface]::Invoke) -or -not $UI.open.IsTabStop){throw 'Application opener lost keyboard/accessibility support'}
foreach($workHeight in @(600,768,1080)){if($height -gt [Math]::Floor($workHeight*.85)){throw 'Compact frame exceeds work-area budget'};$p=Get-WidgetPlacement ([Windows.Rect]::new(0,0,800,$workHeight)) 340 $height 700 ($workHeight-10);if($p.Left+340 -gt 800 -or $p.Top+$height -gt $workHeight){throw 'Compact placement outside work area'}}
foreach($key in @('title','sub','pill','compactcpu','compactram','compactdisk','compactAlert','open')){$node=$UI[$key];$b=$node.TransformToAncestor($win.Content).TransformBounds([Windows.Rect]::new(0,0,$node.ActualWidth,$node.ActualHeight));if($b.Left -lt -.5 -or $b.Right -gt 340.5 -or $b.Top -lt -.5 -or $b.Bottom -gt $height+.5){throw 'Compact control outside frame'}}
Write-Output 'PASS actual single-surface tree: three action controls, no pages/expander/scroll, accessible opener; content/frame geometry and600/768/1080 work-area bounds'
Update-Compact (Fresh-Data);if($UI.pillText.Text -ne 'مستقر' -or $UI.compactcpu.Text -notmatch '24'){throw 'Fresh metrics missing'}
$d=Fresh-Data;$d.now=(Get-Date).AddMinutes(-5).ToString('s');Update-Compact $d;if($UI.pillText.Text -ne 'قديم' -or $UI.compactcpu.Text -ne '—'){throw 'Stale source presented as live'}
$d=Fresh-Data;$d.m.ramPct=$null;$d.m.diskFreeGB=$null;Update-Compact $d;if($UI.pillText.Text -ne 'ناقص' -or $UI.compactram.Text -ne '—' -or $UI.compactdisk.Text -ne '—'){throw 'Missing metrics inferred healthy or zero'}
$script:sync.data=$null;Update-Widget;if($UI.pillText.Text -ne 'غير متصل'){throw 'Disconnected state missing'}
$script:sync.data=Fresh-Data;$script:sync.data.m.ramPct=99;Update-Widget;if($UI.pillText.Text -ne 'حرج' -or $UI.compactAlert.Text -notmatch 'ذاكرة'){throw 'Critical RAM omitted from compact state'}
Show-Toast ('تعذّر '+('رسالة طويلة '*100));if($UI.toast.Text.Length -gt 96 -or -not $script:lastLog){throw 'Long feedback grows compact frame or is not logged'};$script:toastUntil=[datetime]::MinValue;Update-Widget
Write-Output 'PASS fresh/stale/missing/disconnected/critical-RAM states and bounded feedback; detailed maintenance producers absent'
foreach($v in @([double]::NaN,[double]::PositiveInfinity,$null,$true,'invalid')){if((Normalize-WidgetOpacity $v) -ne .96){throw 'Invalid opacity accepted'}}
foreach($v in @(.1,.25,.5,.96,1)){Set-CardOpacity $v;if($card.Background.Color.A -ne [byte][Math]::Round(255*$v) -or $win.Opacity -ne 1 -or $UI.compactcpu.Opacity -ne 1){throw 'Opacity fades content or does not follow background setting'}}
$minimum=100.0;$revision=1
foreach($light in @($true,$false)){foreach($palette in @('teal','blue','violet','graphite')){$mode=if($light){'light'}else{'dark'};Receive-Appearance ([pscustomobject]@{schemaVersion=1;revision=$revision;mode=$mode;palette=$palette});$revision++;$null=Layout-Compact
    if($script:S.palette -ne $palette -or $script:isLight -ne $light){throw 'Shared appearance not applied'}
    foreach($button in @($UI.open,$UI.menuBtn,$UI.closeBtn)){foreach($state in @('normal','hover','disabled')){$button.IsEnabled=($state -ne 'disabled');$event=New-Object Windows.Input.MouseEventArgs([Windows.Input.Mouse]::PrimaryDevice,[Environment]::TickCount);$event.RoutedEvent=if($state -eq 'hover'){[Windows.Input.Mouse]::MouseEnterEvent}else{[Windows.Input.Mouse]::MouseLeaveEvent};$button.RaiseEvent($event);$null=$button.ApplyTemplate();$null=Layout-Compact;$frame=$button.Template.FindName('Frame',$button);foreach($text in @(Text-Nodes $button)){$fg=[Windows.Documents.TextElement]::GetForeground($text);$r=Ratio $fg.Color $frame.Background.Color;if($fg.Color.A -ne 255 -or $frame.Background.Color.A -ne 255 -or $r -lt 4.5 -or $button.Opacity -ne 1){throw 'Compact command text disappears in theme/state'};$minimum=[Math]::Min($minimum,$r)}};$button.IsEnabled=$true}
}}
$before=$script:appearanceRevision;foreach($bad in @($true,-1,'1',1.5,$null)){$record=[pscustomobject]@{schemaVersion=1;revision=$bad;mode='light';palette='teal'};Receive-Appearance $record;if($script:appearanceRevision -ne $before){throw 'Invalid appearance revision accepted'}}
$confirmed=$script:S.palette;Receive-Appearance ([pscustomobject]@{schemaVersion=1;revision=0;mode='auto';palette='teal';recoveryRequired=$true});if(-not $script:appearanceRecoveryRequired -or $script:S.palette -ne $confirmed){throw 'Recovery fallback overwrote last confirmed appearance'}
$script:sync.data=Fresh-Data;Update-Compact $script:sync.data;if($UI.compactAlert.Text -notmatch 'إصلاح'){throw 'Appearance recovery is not visible in single compact alert'}
$script:appearanceRecoveryRequired=$false;$script:appearancePending=$false
function Start-Bg($path,$body,$ok,$err){$script:posted=@{path=$path;body=$body};& $err 'synthetic rejection'}
Request-Appearance 'light' 'teal';if($script:posted.path -ne '/api/appearance' -or $script:posted.body.revision -ne $script:appearanceRevision -or $script:S.palette -ne $confirmed -or $script:appearancePending){throw 'Failed appearance save applied optimistically or CAS omitted'}
Write-Output ('PASS all8 native appearance pairs and actual button Content/template states; minimum contrast '+$minimum.ToString('N2')+':1; opacity, strict revisions, recovery and failed CAS save preserved')
$tmp=Join-Path ([IO.Path]::GetTempPath()) ('mw-compact-test-'+[guid]::NewGuid().ToString('N'));[void][IO.Directory]::CreateDirectory($tmp)
try{$script:setPath=Join-Path $tmp 'widget.settings.json';[IO.File]::WriteAllText($script:setPath,'{"theme":"light","legacy":42}');$script:S.left=77;Save-Settings;$stored=Get-Content -LiteralPath $script:setPath -Raw|ConvertFrom-Json;if($stored.theme -ne 'light' -or $stored.legacy -ne 42 -or $stored.left -ne 77){throw 'Local settings overwrote appearance or unrelated data'}}finally{$resolved=[IO.Path]::GetFullPath($tmp);if(-not $resolved.StartsWith([IO.Path]::GetFullPath([IO.Path]::GetTempPath()),[StringComparison]::OrdinalIgnoreCase) -or [IO.Path]::GetFileName($resolved) -notmatch '^mw-compact-test-[a-f0-9]{32}$'){throw 'Unsafe cleanup path'};Remove-Item -LiteralPath $resolved -Recurse -Force}
